-- The FINISHRED code key (Code keys -> Milling -> FINISHRED), from the ISCAR
-- e-catalog's FINISHRED families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.finishred', $ck${"title": "FINISHRED code key – combined roughing and finishing endmills", "subtitle": "Solid carbide endmills that rough and finish with a single tool (EFS-B44, CHATTER-FREE EFS-E44) and their kit", "example": "EFS-B44 10-22C10-72", "decoder": "finishred", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "EFS", "rows": [{"code": "EFS", "meaning": "Combined roughing and finishing endmill"}, {"code": "KIT", "meaning": "Kit of endmills"}]}, {"key": "t-helix", "title": "Helix", "rows": [{"code": "B", "meaning": "45° helix"}, {"code": "E", "meaning": "38° helix"}]}, {"key": "t-dims", "title": "Geometry / dimension code", "rows": [{"code": "…", "meaning": "Further code (see the catalog)"}]}, {"key": "t-dia", "title": "Cutting diameter", "rows": [{"code": "##", "meaning": "Diameter in mm"}, {"code": "###", "meaning": "Diameter x10 (compact designations) or mm with decimals (015 = 1.5 mm)"}]}, {"key": "t-apmx", "title": "Cutting length", "rows": [{"code": "##", "meaning": "Cutting length in mm"}]}, {"key": "t-neck", "title": "Neck (reach) length", "rows": [{"code": "/##", "meaning": "Length to the neck end in mm"}]}, {"key": "s-shank", "title": "Shank type", "rows": [{"code": "C", "meaning": "Cylindrical shank"}, {"code": "SL", "meaning": "Safe-Lock shank (by Haimer), helical grooves that prevent pull-out"}, {"code": "W", "meaning": "Weldon shank"}]}, {"key": "s-dia", "title": "Shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "t-cf", "title": "CHATTER-FREE", "rows": [{"code": "CF", "meaning": "CHATTER-FREE: different helix and variable pitch for chatter damping"}]}, {"key": "t-oal", "title": "Overall length", "rows": [{"code": "##", "meaning": "Overall length in mm"}, {"code": "###", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Suffix", "rows": [{"code": "C", "meaning": "With coolant holes / channels"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
